begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='042_followup_filters') then raise exception 'Apply Database60.sql first.';end if;end$$;
create function public.jf_order_amount_value(value text) returns numeric language plpgsql immutable security invoker set search_path='' as $$
begin
 value:=regexp_replace(regexp_replace(value,'[৳,[:space:]]','','g'),'^(BDT|Tk)|(BDT|Tk)$','','gi');
 if value is null or value !~ '^[0-9]+([.][0-9]{1,2})?$' then return null;end if;
 return value::numeric;
end$$;
create function public.jf_customer_order_amount(target_shop uuid,target_customer uuid) returns numeric language sql stable security invoker set search_path='' as $$
 select sum(amount) from (
  select o.total amount from public.jf_orders o where o.shop_id=target_shop and o.customer_id=target_customer and o.archived_at is null
  union all
  select public.jf_order_amount_value(h.details->>'total') amount from public.jf_order_history h where h.shop_id=target_shop and h.customer_id=target_customer
   and not exists(select 1 from public.jf_orders o where o.shop_id=h.shop_id and o.customer_id=h.customer_id and o.archived_at is null and lower(trim(o.order_number))=lower(trim(h.external_id)))
 ) amounts;
$$;
revoke all on function public.jf_order_amount_value(text),public.jf_customer_order_amount(uuid,uuid) from public,anon;
grant execute on function public.jf_order_amount_value(text),public.jf_customer_order_amount(uuid,uuid) to authenticated;
create or replace function public.jf_payment_filter_match(amount_text text,ranges text) returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare amount numeric;part text;lo numeric;hi numeric;
begin
 if nullif(ranges,'') is null then return true;end if;
 amount_text:=regexp_replace(regexp_replace(amount_text,'[৳,[:space:]]','','g'),'^(BDT|Tk)|(BDT|Tk)$','','gi');
 if amount_text is null or amount_text !~ '^[0-9]+([.][0-9]{1,2})?$' then return false;end if;
 amount:=amount_text::numeric;
 foreach part in array string_to_array(ranges,',') loop
  if part not in('0:500','100:500','500:1000','1000:2000','2000:3000','3000:4000','4000:5000','5000:6000','6000:7000','7000:8000','8000:9000','9000:10000') then raise exception 'Invalid payment range.';end if;
  lo:=case when part='100:500' then 0 else split_part(part,':',1)::numeric end;hi:=split_part(part,':',2)::numeric;
  if amount>=lo and (amount<hi or hi=10000 and amount=10000) then return true;end if;
 end loop;return false;
end$$;
revoke all on function public.jf_payment_filter_match(text,text) from public,anon;
grant execute on function public.jf_payment_filter_match(text,text) to authenticated;
create or replace function public.jf_workspace_page(target_shop uuid,entity text,filters jsonb default '{}',page_number integer default 0) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;st text:=coalesce(filters->>'status','all');search text:=trim(coalesce(filters->>'search',''));agent_id uuid:=nullif(filters->>'agent_id','')::uuid;
begin
 if page_number is null or page_number<0 or length(search)>200 then raise exception 'Invalid page filter.';end if;

 if exists(select 1 from jsonb_each_text(filters) x where x.key like 'af\_%' escape '\' and coalesce(x.value,'')<>'') then
  if not coalesce(jioflow_private.reads_operations(target_shop),false) or jioflow_private.agent_member(target_shop) is not null then raise exception 'Advanced follow-up filters require Creator, Owner or Admin access.' using errcode='42501';end if;
  if nullif(filters->>'af_payment_basis','') is not null and filters->>'af_payment_basis' not in('total','advance') then raise exception 'Choose total or advance payment.';end if;
  if nullif(filters->>'af_payment_ranges','') is not null and exists(select 1 from unnest(string_to_array(filters->>'af_payment_ranges',',')) p where p not in('0:500','100:500','500:1000','1000:2000','2000:3000','3000:4000','4000:5000','5000:6000','6000:7000','7000:8000','8000:9000','9000:10000')) then raise exception 'Invalid payment range.';end if;
  if entity<>'customers' then raise exception 'Advanced filters apply to follow-ups.';end if;
  if exists(select 1 from jsonb_each_text(filters) x where x.key like 'af\_%' escape '\' and length(x.value)>200) then raise exception 'Filter value is too long.';end if;
  if exists(select 1 from jsonb_each_text(filters) x where x.key in('af_order_date','af_created_from','af_created_to','af_updated_from','af_updated_to','af_order_from','af_order_to') and nullif(x.value,'') is not null and (x.value !~ '^\d{4}-\d{2}-\d{2}$' or public.jf_filter_date(x.value) is null)) then raise exception 'Use a valid filter date.';end if;
  if nullif(filters->>'af_created_from','')::date>nullif(filters->>'af_created_to','')::date or nullif(filters->>'af_updated_from','')::date>nullif(filters->>'af_updated_to','')::date or nullif(filters->>'af_order_from','')::date>nullif(filters->>'af_order_to','')::date then raise exception 'Start date must not follow end date.';end if;
 end if;
 if entity='customers' then
  with base as materialized(select c.*,f.status followup_status,f.call_outcome,f.callback_at,(buyers.customer_id is not null) has_confirmed from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id left join (select distinct x.customer_id from public.jf_orders x where x.shop_id=target_shop and x.archived_at is null and x.status not in('draft','cancelled')) buyers on buyers.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)

   and (nullif(filters->>'af_agent','') is null or c.assigned_membership_id=(filters->>'af_agent')::uuid)
   and (nullif(filters->>'af_customer_status','') is null or f.call_outcome=lower(filters->>'af_customer_status') or lower(c.workflow_label)=lower(filters->>'af_customer_status') or f.status=filters->>'af_customer_status')
   and (nullif(filters->>'af_call_status','') is null or coalesce(f.call_outcome,'not_attempted')=filters->>'af_call_status' or filters->>'af_call_status'='connected' and f.call_outcome in('connected','positive','negative','intermediate') or filters->>'af_call_status'='not_connected' and f.call_outcome in('not_connected','no_answer','busy'))
   and (nullif(filters->>'af_created_from','') is null or c.created_at>=(filters->>'af_created_from')::date::timestamp at time zone 'Asia/Dhaka')
   and (nullif(filters->>'af_created_to','') is null or c.created_at<((filters->>'af_created_to')::date+1)::timestamp at time zone 'Asia/Dhaka')
   and (nullif(filters->>'af_updated_from','') is null or c.updated_at>=(filters->>'af_updated_from')::date::timestamp at time zone 'Asia/Dhaka')
   and (nullif(filters->>'af_updated_to','') is null or c.updated_at<((filters->>'af_updated_to')::date+1)::timestamp at time zone 'Asia/Dhaka')
   and (not exists(select 1 from jsonb_each_text(filters) x where x.key in('af_order_date','af_order_from','af_order_to','af_imported_status','af_sku','af_source','af_tag','af_tag2','af_tag3','af_payment_ranges') and coalesce(x.value,'')<>'')
    or exists(select 1 from public.jf_order_history h where h.shop_id=target_shop and h.customer_id=c.id
     and (nullif(filters->>'af_order_date','') is null or public.jf_filter_date(coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at'))=(filters->>'af_order_date')::date)
     and (nullif(filters->>'af_order_from','') is null or public.jf_filter_date(coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at'))>=(filters->>'af_order_from')::date)
     and (nullif(filters->>'af_order_to','') is null or public.jf_filter_date(coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at'))<=(filters->>'af_order_to')::date)
     and (nullif(filters->>'af_imported_status','') is null or lower(h.details->>'status')=lower(filters->>'af_imported_status'))
     and (nullif(filters->>'af_sku','') is null or public.jf_import_filter_value(h.details,'sku') ilike '%'||(filters->>'af_sku')||'%')
     and (nullif(filters->>'af_source','') is null or lower(coalesce(nullif(public.jf_import_filter_value(h.details,'source'),''),c.source))=lower(filters->>'af_source'))
     and (nullif(filters->>'af_tag','') is null or c.unassignment_tag=filters->>'af_tag' or coalesce(nullif(public.jf_import_filter_value(h.details,'custom_tag'),''),h.details->>'reference_tag')=filters->>'af_tag')
     and (nullif(filters->>'af_tag2','') is null or public.jf_import_filter_value(h.details,'custom_tag_2')=filters->>'af_tag2')
     and (nullif(filters->>'af_tag3','') is null or public.jf_import_filter_value(h.details,'custom_tag_3')=filters->>'af_tag3')
     and public.jf_payment_filter_match(h.details->>case when filters->>'af_payment_basis'='advance' then 'advance' else 'total' end,filters->>'af_payment_ranges'))
    or nullif(filters->>'af_imported_status','') is null and nullif(filters->>'af_tag2','') is null and nullif(filters->>'af_tag3','') is null and
     (nullif(filters->>'af_tag','') is null or c.unassignment_tag=filters->>'af_tag') and
     ((nullif(filters->>'af_order_date','') is null and nullif(filters->>'af_order_from','') is null and nullif(filters->>'af_order_to','') is null and nullif(filters->>'af_sku','') is null and nullif(filters->>'af_payment_ranges','') is null and (nullif(filters->>'af_source','') is null or lower(c.source)=lower(filters->>'af_source')))
      or exists(select 1 from public.jf_orders z where z.shop_id=target_shop and z.customer_id=c.id and z.archived_at is null
       and (nullif(filters->>'af_order_date','') is null or (z.created_at at time zone 'Asia/Dhaka')::date=(filters->>'af_order_date')::date)
       and (nullif(filters->>'af_order_from','') is null or (z.created_at at time zone 'Asia/Dhaka')::date>=(filters->>'af_order_from')::date)
       and (nullif(filters->>'af_order_to','') is null or (z.created_at at time zone 'Asia/Dhaka')::date<=(filters->>'af_order_to')::date)
       and (nullif(filters->>'af_source','') is null or lower(z.source)=lower(filters->>'af_source'))
       and public.jf_payment_filter_match(case when filters->>'af_payment_basis'='advance' then (select coalesce(sum(p.amount),0)::text from public.jf_payments p where p.shop_id=z.shop_id and p.order_id=z.id and p.status in('pending','verified')) else z.total::text end,filters->>'af_payment_ranges')
       and (nullif(filters->>'af_sku','') is null or exists(select 1 from public.jf_order_items i join public.jf_products p on p.shop_id=i.shop_id and p.id=i.product_id where i.shop_id=z.shop_id and i.order_id=z.id and p.sku ilike '%'||(filters->>'af_sku')||'%')))))
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and (coalesce(filters->>'response','')='' or f.call_outcome=lower(filters->>'response')) and (coalesce(filters->>'call','')='' or lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')) and (search='' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%' or c.address ilike '%'||search||'%')),c as(select * from base c where (st='confirmed' and c.has_confirmed or st='attempted' and c.call_outcome is not null and c.call_outcome<>'not_attempted' or st='failed' and c.call_outcome is not null and c.call_outcome<>'not_attempted' and not c.has_confirmed or lower(replace(c.workflow_label,' ','_'))=st or st in('no_answer','busy') and c.call_outcome=st or st='all' or st='unassigned' and c.assigned_membership_id is null or st='assigned' and c.assigned_membership_id is not null or st='permanent' and c.permanent or st='completed' and c.followup_status='completed' or st='pending' and coalesce(c.followup_status,'pending') in ('pending','callback') or st='cancelled' and c.followup_status='cancelled' or st='connected' and c.call_outcome in ('connected','positive','negative','intermediate') or st='not_connected' and c.call_outcome in ('not_connected','no_answer','busy') or st='not_attempted' and (c.call_outcome is null or c.call_outcome='not_attempted') or st in ('positive','negative','intermediate') and c.call_outcome=st or st='callback' and c.followup_status='callback' or st='callbacks' and c.followup_status='callback' and c.callback_at<=now() or st='buyers' and c.followup_status='completed' and c.has_confirmed))
  select jsonb_build_object('counts',coalesce((select jsonb_object_agg(k,n) from(select lower(replace(workflow_label,' ','_')) k,count(*) n from base where nullif(workflow_label,'') is not null group by 1) labels),'{}'::jsonb)||(select jsonb_build_object('all',count(*) filter(where true),'assigned',count(*) filter(where assigned_membership_id is not null),'unassigned',count(*) filter(where assigned_membership_id is null),'completed',count(*) filter(where followup_status='completed'),'pending',count(*) filter(where coalesce(followup_status,'pending') in('pending','callback')),'cancelled',count(*) filter(where followup_status='cancelled'),'permanent',count(*) filter(where permanent),'connected',count(*) filter(where call_outcome in('connected','positive','negative','intermediate')),'not_connected',count(*) filter(where call_outcome in('not_connected','no_answer','busy')),'not_attempted',count(*) filter(where call_outcome is null or call_outcome='not_attempted'),'attempted',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted'),'confirmed',count(*) filter(where has_confirmed),'failed',count(*) filter(where call_outcome is not null and call_outcome<>'not_attempted' and not has_confirmed),'buyers',count(*) filter(where followup_status='completed' and has_confirmed),'callback',count(*) filter(where followup_status='callback'),'callbacks',count(*) filter(where followup_status='callback' and callback_at<=now()),'positive',count(*) filter(where call_outcome='positive'),'negative',count(*) filter(where call_outcome='negative'),'intermediate',count(*) filter(where call_outcome='intermediate'),'no_answer',count(*) filter(where call_outcome='no_answer'),'busy',count(*) filter(where call_outcome='busy')) from base),'total',(select count(*) from c),'rows',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('order_date',coalesce((select coalesce(h.details->>'ordered_at',h.details->>'order_date',h.details->>'created_at') from public.jf_order_history h where h.shop_id=target_shop and h.customer_id=p.id order by h.updated_at desc,h.id limit 1),(select o.created_at::text from public.jf_orders o where o.shop_id=target_shop and o.customer_id=p.id and o.archived_at is null order by o.created_at desc,o.id limit 1)),'latest_note',(select n.body from public.jf_notes n where n.shop_id=target_shop and n.customer_id=p.id order by n.created_at desc,n.id desc limit 1),'order_amount',public.jf_customer_order_amount(target_shop,p.id),'order_count',(select count(*) from public.jf_orders z where z.shop_id=target_shop and z.customer_id=p.id and z.archived_at is null))) from(select * from c order by updated_at desc,id limit 50 offset page_number::bigint*50) p),'[]')) into result;
 elsif entity='orders' then
  with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),entries as materialized(select to_jsonb(l)||jsonb_build_object('is_imported',false) entry,l.id,l.created_at from live l),matching as(select * from entries where st='all' or st='imported' and coalesce((entry->>'is_imported')::boolean,false) or st='confirmed' and entry->>'status' not in('draft','cancelled','imported') or st='ready_to_book' and entry->>'status' in('confirmed','ready_to_book') or st not in('all','imported','confirmed','ready_to_book') and entry->>'status'=st)
  select jsonb_build_object('counts',(select jsonb_build_object('all',count(*) filter(where true),'imported',count(*) filter(where coalesce((entry->>'is_imported')::boolean,false)),'confirmed',count(*) filter(where entry->>'status' not in('draft','cancelled','imported')),'ready_to_book',count(*) filter(where entry->>'status' in('confirmed','ready_to_book')),'draft',count(*) filter(where entry->>'status'='draft'),'booked',count(*) filter(where entry->>'status'='booked'),'in_transit',count(*) filter(where entry->>'status'='in_transit'),'delivered',count(*) filter(where entry->>'status'='delivered'),'partial_delivery',count(*) filter(where entry->>'status'='partial_delivery'),'returned',count(*) filter(where entry->>'status'='returned'),'cancelled',count(*) filter(where entry->>'status'='cancelled'),'exchange',count(*) filter(where entry->>'status'='exchange'),'replacement',count(*) filter(where entry->>'status'='replacement')) from entries),'total',(select count(*) from matching),'rows',coalesce((select jsonb_agg(entry order by created_at desc,id) from(select * from matching order by created_at desc,id limit 50 offset page_number::bigint*50)p),'[]'::jsonb)) into result;
 else raise exception 'Choose customers or orders.';end if;
 return result;
end $$;


insert into public.jf_schema_versions(version) values('043_followup_amount') on conflict do nothing;
